// Builds supabase/functions/_shared/lab-bundle.js: the Fight Lab's code, as a
// real module an edge function can import, instead of source text it fetches
// from Pages and runs with `new Function`.
//
// Why: send-reminders composed the Friday brief (and matched names for fight
// change alerts) by fetching lab/engine.js, lab/analytics.js, scoring.js and
// index.html from GitHub Pages and evaluating them in an isolate that also
// holds the service-role key. Whoever could change what Pages served could
// read that key. Bundled, the code is whatever this commit says it is.
//
// What goes in, exactly as the app and the Lab run it:
//   engineInto(root)     lab/engine.js      (sets root.PickEngine)
//   analyticsInto(root)  lab/analytics.js   (sets root.FightLab)
//   kernelFactory(...)   scoring.js + the index.html slices PickEngine.loadKernel
//                        lifts (captured by running loadKernel itself, so the
//                        slicing can never drift from the Lab's)
//   bundledKernel(env)   loadKernel's own call of that factory, env → kernel
//
//   node scripts/build-fn-bundle.mjs           write the bundle
//   node scripts/build-fn-bundle.mjs --check   fail if it's stale (check:bundle)
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import vm from "node:vm";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(ROOT, "supabase/functions/_shared/lab-bundle.js");
const read = (f) => readFileSync(join(ROOT, f), "utf8");

export function buildBundle() {
  const engineSrc = read("lab/engine.js"), analyticsSrc = read("lab/analytics.js");
  const scoringSrc = read("scoring.js"), html = read("index.html");

  const ctx = vm.createContext({});
  vm.runInContext(engineSrc, ctx);
  const PE = ctx.PickEngine;
  if (!PE || typeof PE.loadKernel !== "function") throw new Error("lab/engine.js no longer exposes PickEngine.loadKernel");

  // Run the real loadKernel with a compile() that records what it would have
  // compiled, and a factory that records the arguments it passes.
  let params = null, body = null, args = null;
  const S = { EVENTS: ["__EVENTS__"], RESULTS_ARCHIVE: { __RA__: 1 }, FIGHTER_STATS: { __FS__: 1 }, RANKINGS: { __RK__: 1 }, USER_ID: "__USER__" };
  PE.loadKernel(html, S, (p, b) => {
    params = p.slice(); body = b;
    return (...a) => { args = a; return new Proxy({}, { get: () => true }); };
  }, scoringSrc);
  const WANT = ["EVENTS", "RESULTS_ARCHIVE", "FIGHTER_STATS", "RANKINGS", "USER_ID",
                "MAIN_CARD_BOUTS", "DAY_MS", "lbScope", "userName", "_lbRows", "_commRows", "console"];
  if (JSON.stringify(params) !== JSON.stringify(WANT)) {
    throw new Error("loadKernel's parameter list changed: update build-fn-bundle.mjs (" + JSON.stringify(params) + ")");
  }
  if (args[0] !== S.EVENTS || args[1] !== S.RESULTS_ARCHIVE || args[2] !== S.FIGHTER_STATS || args[3] !== S.RANKINGS || args[4] !== S.USER_ID) {
    throw new Error("loadKernel no longer passes env through in order: update build-fn-bundle.mjs");
  }
  const tail = args.slice(5, 11);   // MAIN_CARD_BOUTS … _commRows: plain constants
  if (!tail.every((v) => v === null || ["number", "string"].includes(typeof v))) throw new Error("loadKernel's constant arguments are no longer plain values");
  const exportsMatch = /var KERNEL_EXPORTS = (\[[\s\S]*?\]);/.exec(engineSrc);
  const exportsList = exportsMatch && vm.runInNewContext(exportsMatch[1]);
  if (!Array.isArray(exportsList) || !exportsList.length) throw new Error("lab/engine.js KERNEL_EXPORTS not found");

  return [
    "// GENERATED by scripts/build-fn-bundle.mjs from lab/engine.js, lab/analytics.js,",
    "// scoring.js and the index.html slices PickEngine.loadKernel lifts. Do not edit:",
    "// run `npm run build:fn`. `npm run check:bundle` (in verify) fails when it's stale.",
    "/* eslint-disable */",
    "",
    "export function engineInto(globalThis) {",
    engineSrc,
    "}",
    "",
    "export function analyticsInto(globalThis) {",
    analyticsSrc,
    "}",
    "",
    `export function kernelFactory(${params.join(", ")}) {`,
    body,
    "}",
    "",
    `export const KERNEL_EXPORTS = ${JSON.stringify(exportsList)};`,
    "// loadKernel's own call of the factory, with the same constants.",
    "export function bundledKernel(env) {",
    "  env = env || {};",
    "  const quiet = { log() {}, warn() {}, error() {} };",
    `  const k = kernelFactory(env.EVENTS || [], env.RESULTS_ARCHIVE || {}, env.FIGHTER_STATS || {}, env.RANKINGS || {}, env.USER_ID || null, ${tail.map((v) => JSON.stringify(v)).join(", ")}, quiet);`,
    "  for (const n of KERNEL_EXPORTS) if (k[n] === undefined) throw new Error(\"bundled kernel: \" + n + \" missing\");",
    "  return k;",
    "}",
    "",
  ].join("\n");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const next = buildBundle();
  if (process.argv.includes("--check")) {
    const cur = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
    if (cur !== next) {
      console.error("✗ supabase/functions/_shared/lab-bundle.js is stale: lab/engine.js, lab/analytics.js,");
      console.error("  scoring.js or index.html changed without it. Run `npm run build:fn` and commit the result.");
      process.exit(1);
    }
    // parseDataJs must read data.js exactly as running it would. The frozen
    // fixture fails the check; the live file only warns, since this gate runs
    // before every Pages deploy and a data mismatch must never block live results
    // (the brief then falls back to its plain teaser until the parser is fixed).
    const { parseDataJs } = await import("../supabase/functions/_shared/datajs.js");
    for (const f of ["tests/fixtures/fight-week/data.js", "data.js"]) {
      if (!existsSync(join(ROOT, f))) continue;
      const live = f === "data.js";
      const src = read(f), ctx = vm.createContext({});
      vm.runInContext(src + "\n;this.__out={EVENTS,RESULTS_ARCHIVE:typeof RESULTS_ARCHIVE!=='undefined'?RESULTS_ARCHIVE:undefined,FIGHTER_STATS:typeof FIGHTER_STATS!=='undefined'?FIGHTER_STATS:undefined,RANKINGS:typeof RANKINGS!=='undefined'?RANKINGS:undefined};", ctx);
      const want = JSON.stringify(ctx.__out);
      let got = null;
      try { got = parseDataJs(src); } catch (e) { got = { error: e.message }; }
      if (JSON.stringify({ EVENTS: got.EVENTS, RESULTS_ARCHIVE: got.RESULTS_ARCHIVE, FIGHTER_STATS: got.FIGHTER_STATS, RANKINGS: got.RANKINGS }) !== want) {
        const msg = "parseDataJs reads " + f + " differently from running it" + (got.error ? " (" + got.error + ")" : "") + ": fix supabase/functions/_shared/datajs.js";
        if (live) { console.log("::warning::" + msg); continue; }
        console.error("✗ " + msg);
        process.exit(1);
      }
    }
    for (const bad of ['var EVENTS=[f()];', 'var EVENTS=[1+1];', 'var EVENTS=[x];', 'EVENTS=[];', 'var EVENTS=["a"];(0)']) {
      let threw = false;
      try { parseDataJs(bad); } catch (_e) { threw = true; }
      if (!threw) { console.error("✗ parseDataJs accepted code: " + bad); process.exit(1); }
    }
    console.log("check:bundle — the edge functions' bundled Lab code matches its sources, and data.js parses without running");
  } else {
    writeFileSync(OUT, next);
    console.log("wrote " + OUT.slice(ROOT.length + 1) + " (" + (next.length / 1024).toFixed(0) + " KB)");
  }
}
